<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#1e293b;margin:24px}.head{text-align:center;border-bottom:3px solid #4338ca;padding-bottom:12px}.head h2{margin:0;color:#312e81}.tag{font-size:15px;font-weight:bold;margin:16px 0;text-align:center}.line{border-bottom:1px solid #e2e8f0;padding:9px 0}.amount{background:#eef2ff;padding:13px;margin:14px 0;font-size:16px;font-weight:bold;text-align:center}.foot{text-align:center;margin-top:24px;color:#64748b;font-size:9px}</style></head><body><div class="head"><h2>{{ $company?->name ?? 'Établissement' }}</h2><div>{{ $company?->address }}</div><div>{{ $company?->phone }}</div></div><div class="tag">REÇU DE PAIEMENT</div><div class="line"><b>Référence :</b> {{ $payment->reference }}</div><div class="line"><b>Date :</b> {{ $payment->paid_on?->format('d/m/Y') }}</div><div class="line"><b>Élève :</b> {{ $account->enrollment?->student?->last_name }} {{ $account->enrollment?->student?->first_name }}</div><div class="line"><b>Matricule :</b> {{ $account->enrollment?->student?->student_number }}</div><div class="line"><b>Classe :</b> {{ $account->enrollment?->schoolClass?->name }}</div><div class="line"><b>Année scolaire :</b> {{ $account->enrollment?->year?->name }}</div><div class="line"><b>Rubrique :</b> {{ ['registration_fee'=>'Inscription','installment_1'=>'Tranche 1','installment_2'=>'Tranche 2','installment_3'=>'Tranche 3'][$payment->fee_type] ?? $payment->fee_type }}</div><div class="line"><b>Mode :</b> {{ ['cash'=>'Espèces','bank_transfer'=>'Virement','orange_money'=>'Orange Money','mtn_momo'=>'MTN MoMo'][$payment->method] ?? $payment->method }}</div><div class="amount">Montant reçu : {{ number_format($payment->amount,0,',',' ') }} FCFA</div><div class="line"><b>Total facturé :</b> {{ number_format($due,0,',',' ') }} FCFA</div><div class="line"><b>Total encaissé à cette date :</b> {{ number_format($paidThroughReceipt,0,',',' ') }} FCFA</div><div class="line"><b>Solde après ce versement :</b> {{ number_format(max(0,$due-$paidThroughReceipt),0,',',' ') }} FCFA</div><div class="foot">Document généré par NEXORA — Référence unique {{ $payment->reference }}</div></body></html>